-- CHAMBA 020 — Límites: cliente máx. 2 solicitudes activas; técnico máx. 2 chambas activasSET statement_timeout = '120s';-- ── Contadores ─────────────────────────────────────────────────────────────CREATE OR REPLACE FUNCTION DROP FUNCTION IF EXISTS count_client_active_jobs CASCADE;CREATE OR REPLACE FUNCTION count_client_active_jobs(p_client_id UUID)RETURNS INTLANGUAGE sqlSTABLESECURITY DEFINERSET search_path = publicAS $$  SELECT COUNT(*)::INT  FROM jobs  WHERE created_by = p_client_id    AND status::text NOT IN ('completed', 'cancelled');$$;CREATE OR REPLACE FUNCTION DROP FUNCTION IF EXISTS count_worker_active_commitments CASCADE;CREATE OR REPLACE FUNCTION count_worker_active_commitments(p_worker_id UUID)RETURNS INTLANGUAGE sqlSTABLESECURITY DEFINERSET search_path = publicAS $$  SELECT COUNT(DISTINCT j.id)::INT  FROM job_assignments ja  JOIN jobs j ON j.id = ja.job_id  WHERE ja.worker_id = p_worker_id    AND j.status::text NOT IN ('completed', 'cancelled')    AND ja.selection_status IN ('pending', 'approved');$$;GRANT EXECUTE ON FUNCTION count_client_active_jobs(UUID) TO anon, authenticated;GRANT EXECUTE ON FUNCTION count_worker_active_commitments(UUID) TO anon, authenticated;-- ── create_client_job: máx. 2 solicitudes activas por cliente ───────────────CREATE OR REPLACE FUNCTION DROP FUNCTION IF EXISTS create_client_job CASCADE;CREATE OR REPLACE FUNCTION create_client_job(  p_created_by       UUID,  p_title            TEXT,  p_description      TEXT,  p_category         TEXT,  p_pay_amount       NUMERIC,  p_address          TEXT,  p_lat              DOUBLE PRECISION,  p_lng              DOUBLE PRECISION,  p_duration_hours   NUMERIC DEFAULT 2,  p_required_workers INTEGER DEFAULT 1,  p_scheduled_at     TIMESTAMPTZ DEFAULT NULL,  p_media_urls       TEXT[] DEFAULT '{}')RETURNS JSONBLANGUAGE plpgsqlSECURITY DEFINERSET search_path = publicAS $$DECLARE  v_job    jobs%ROWTYPE;  v_fee    NUMERIC;  v_payout NUMERIC;  v_active INT;  v_max    INT := 2;BEGIN  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = p_created_by) THEN    RETURN jsonb_build_object('success', false, 'error', 'Perfil de cliente no encontrado');  END IF;  v_active := count_client_active_jobs(p_created_by);  IF v_active >= v_max THEN    RETURN jsonb_build_object(      'success', false,      'error', 'Ya tenés 2 solicitudes activas. Cuando una figure como finalizada, podés publicar otra.',      'code', 'client_active_limit',      'active_count', v_active,      'max_allowed', v_max    );  END IF;  v_fee    := ROUND(p_pay_amount * 0.05, 2);  v_payout := ROUND(p_pay_amount * 0.95, 2);  INSERT INTO jobs (    title, description, category, status,    pay_amount, platform_fee, worker_payout,    address, lat, lng, scheduled_at,    duration_hours, required_workers, slots_taken,    media_urls, created_by  ) VALUES (    p_title, p_description, p_category, 'open',    p_pay_amount, v_fee, v_payout,    p_address, p_lat, p_lng, p_scheduled_at,    p_duration_hours, p_required_workers, 0,    COALESCE(p_media_urls, '{}'), p_created_by  )  RETURNING * INTO v_job;  RETURN jsonb_build_object('success', true, 'job', to_jsonb(v_job));EXCEPTION  WHEN OTHERS THEN    RETURN jsonb_build_object('success', false, 'error', SQLERRM);END;$$;-- ── accept_job: máx. 2 chambas activas por técnico ─────────────────────────CREATE OR REPLACE FUNCTION DROP FUNCTION IF EXISTS accept_job CASCADE;CREATE OR REPLACE FUNCTION accept_job(  p_job_id    UUID,  p_worker_id UUID)RETURNS JSONBLANGUAGE plpgsqlSECURITY DEFINERSET search_path = publicAS $$DECLARE  v_job         jobs%ROWTYPE;  v_profile     profiles%ROWTYPE;  v_assignment  job_assignments%ROWTYPE;  v_pending     INT;  v_active      INT;  v_max_apply   INT := 3;  v_max_active  INT := 2;BEGIN  SELECT * INTO v_job FROM jobs WHERE id = p_job_id FOR UPDATE NOWAIT;  IF NOT FOUND THEN    RETURN jsonb_build_object('success', false, 'error', 'Trabajo no encontrado');  END IF;  IF v_job.status::text <> 'open' THEN    RETURN jsonb_build_object('success', false, 'error', 'Este trabajo ya no acepta postulaciones');  END IF;  SELECT * INTO v_profile FROM profiles WHERE id = p_worker_id;  IF NOT FOUND OR v_profile.role::text <> 'worker' THEN    RETURN jsonb_build_object('success', false, 'error', 'Trabajador no encontrado');  END IF;  IF COALESCE(v_profile.is_approved, FALSE) = FALSE THEN    RETURN jsonb_build_object('success', false, 'error', 'Tu cuenta aún no está aprobada por el administrador');  END IF;  v_active := count_worker_active_commitments(p_worker_id);  IF v_active >= v_max_active THEN    RETURN jsonb_build_object(      'success', false,      'error', 'Ya tenés 2 chambas activas (en curso o esperando al cliente). Finalizá una en Agenda para postularte a otra.',      'code', 'worker_active_limit',      'active_count', v_active,      'max_allowed', v_max_active    );  END IF;  IF EXISTS (    SELECT 1 FROM job_assignments    WHERE job_id = p_job_id AND worker_id = p_worker_id  ) THEN    RETURN jsonb_build_object('success', false, 'error', 'Ya postulaste a este trabajo');  END IF;  SELECT COUNT(*)::INT INTO v_pending  FROM job_assignments  WHERE job_id = p_job_id    AND selection_status = 'pending';  IF v_pending >= v_max_apply THEN    RETURN jsonb_build_object(      'success', false,      'error', 'Ya hay 3 técnicos postulando. El cliente está eligiendo.'    );  END IF;  INSERT INTO job_assignments (job_id, worker_id, selection_status)  VALUES (p_job_id, p_worker_id, 'pending')  RETURNING * INTO v_assignment;  RETURN jsonb_build_object(    'success', true,    'assignment_id', v_assignment.id,    'selection_status', 'pending',    'pending_count', v_pending + 1,    'job_id', p_job_id,    'worker_id', p_worker_id  );EXCEPTION  WHEN lock_not_available THEN    RETURN jsonb_build_object('success', false, 'error', 'Otro técnico está postulando. Intentá de nuevo.');  WHEN unique_violation THEN    RETURN jsonb_build_object('success', false, 'error', 'Ya postulaste a este trabajo');END;$$;-- ── Al elegir técnico, validar cupo del técnico ────────────────────────────CREATE OR REPLACE FUNCTION DROP FUNCTION IF EXISTS client_approve_worker_application CASCADE;CREATE OR REPLACE FUNCTION client_approve_worker_application(  p_job_id    UUID,  p_client_id UUID,  p_worker_id UUID)RETURNS JSONBLANGUAGE plpgsqlSECURITY DEFINERSET search_path = publicAS $$DECLARE  v_job jobs%ROWTYPE;  v_assignment_id UUID;  v_active INT;  v_max_active INT := 2;BEGIN  SELECT * INTO v_job FROM jobs WHERE id = p_job_id FOR UPDATE;  IF NOT FOUND OR v_job.created_by <> p_client_id THEN    RETURN jsonb_build_object('success', false, 'error', 'Solicitud no encontrada');  END IF;  IF v_job.status::text <> 'open' THEN    RETURN jsonb_build_object('success', false, 'error', 'Esta solicitud ya fue asignada');  END IF;  SELECT id INTO v_assignment_id  FROM job_assignments  WHERE job_id = p_job_id    AND worker_id = p_worker_id    AND selection_status = 'pending';  IF v_assignment_id IS NULL THEN    RETURN jsonb_build_object('success', false, 'error', 'Este técnico no tiene una postulación activa');  END IF;  v_active := count_worker_active_commitments(p_worker_id);  IF v_active >= v_max_active THEN    RETURN jsonb_build_object(      'success', false,      'error', 'Este técnico ya tiene 2 chambas activas y no puede tomar otra hasta finalizar una.',      'code', 'worker_active_limit'    );  END IF;  UPDATE job_assignments  SET selection_status = 'approved'  WHERE id = v_assignment_id;  UPDATE job_assignments  SET selection_status = 'rejected'  WHERE job_id = p_job_id    AND selection_status = 'pending'    AND worker_id <> p_worker_id;  UPDATE jobs  SET status = 'taken',      assigned_worker_id = p_worker_id,      slots_taken = 1,      operational_phase = 'accepted',      updated_at = NOW()  WHERE id = p_job_id;  RETURN jsonb_build_object(    'success', true,    'assignment_id', v_assignment_id,    'worker_id', p_worker_id  );END;$$;-- Incluir selection_status en agenda del técnicoCREATE OR REPLACE FUNCTION DROP FUNCTION IF EXISTS get_worker_assignments CASCADE;CREATE OR REPLACE FUNCTION get_worker_assignments(p_worker_id UUID)RETURNS JSONBLANGUAGE plpgsqlSECURITY DEFINERSET search_path = publicAS $$DECLARE  v_result JSONB;BEGIN  SELECT COALESCE(    jsonb_agg(      jsonb_build_object(        'id', ja.id,        'job_id', ja.job_id,        'worker_id', ja.worker_id,        'assigned_at', ja.assigned_at,        'completed_at', ja.completed_at,        'payment_status', ja.payment_status,        'payment_intent_id', ja.payment_intent_id,        'selection_status', ja.selection_status,        'job', to_jsonb(j.*)      )      ORDER BY ja.assigned_at DESC    ),    '[]'::jsonb  )  INTO v_result  FROM job_assignments ja  JOIN jobs j ON j.id = ja.job_id  WHERE ja.worker_id = p_worker_id;  RETURN v_result;END;$$;GRANT EXECUTE ON FUNCTION create_client_job TO anon, authenticated;GRANT EXECUTE ON FUNCTION accept_job(UUID, UUID) TO anon, authenticated;GRANT EXECUTE ON FUNCTION client_approve_worker_application(UUID, UUID, UUID) TO anon, authenticated;GRANT EXECUTE ON FUNCTION get_worker_assignments(UUID) TO anon, authenticated;